_MSL = 2


_N = 999999
_E = {}
_CB_MEMO = {}


def _can_bridge(a):
    if not a:
        return True
    r = _CB_MEMO.get(a)
    if r is None:
        r = any(k.endswith(a) for k in _EXC)
        _CB_MEMO[a] = r
    return r


def _opinfo(raw, msl):
    if type(raw) is dict:
        raw = raw.get("")
    if raw is None:
        return _N, None
    if type(raw) is int:
        return raw + msl, ((-raw, '', True) if raw else None)
    c, a = raw
    return max(c + 1, c + msl - len(a)), (((-c if c else None), a, _can_bridge(a)) if (c or a) else None)


def _link(raw, msl, dag, memo):
    out = {}
    for k, v in raw.items():
        if not k:
            continue
        if type(v) in (list, tuple) and len(v) == 1:
            i = v[0]
            v = dag[i]
            child = memo.get(i)
            if child is None:
                child = memo[i] = _link(v, msl, dag, memo) if type(v) is dict else _E
        else:
            child = _link(v, msl, dag, memo) if type(v) is dict else _E
        nd, op = _opinfo(v, msl)
        ent = (child, nd, op)
        for ch in reversed(k[1:]):
            ent = ({ch: ent}, _N, None)
        out[k[0]] = ent
    return out


_ROOT = _link(_RAW, _MSL, (), {}) if type(_RAW) is dict else {}
_ROOT_NEED, _ROOT_OP = _opinfo(_RAW, _MSL)
del _RAW


def _jump(root, root_need, root_op, k=3):
    table = {}

    def rec(node, path, chain, depth):
        if depth == k:
            nd0, op0 = chain[0] if chain else (_N, None)
            table[path] = (node if node else None, nd0, op0, chain[1:])
            return
        for ch, (child, nd, op) in node.items():
            ch_chain = chain
            if nd < _N:
                ch_chain = ((nd, op),) + tuple(c for c in chain if c[0] < nd)
            rec(child, ch + path, ch_chain, depth + 1)

    rec(root, '', ((root_need, root_op),) if root_need < _N else (), 0)
    return table


_jget = _jump(_ROOT, _ROOT_NEED, _ROOT_OP, 3).get


def _lemmatize_word(word: str) -> str:
    if not word:
        return ""
    w = word.lower()
    exc = _EXC.get(w)
    if exc is not None:
        return exc
    wl = len(w)
    t = _jget(w[-3:]) if wl >= 3 else None
    if t is not None:
        node, nd, best, rest = t
        if nd > wl:
            best = None
            for nd, op in rest:
                if nd <= wl:
                    best = op
                    break
        if node is not None:
            i = wl - 4
            while i >= 0:
                ch = w[i]
                if ch not in node:
                    break
                node, nd, op = node[ch]
                if nd <= wl:
                    best = op
                i -= 1
    else:
        best = _ROOT_OP if _ROOT_NEED <= wl else None
        node = _ROOT
        i = wl - 1
        while i >= 0:
            ch = w[i]
            if ch not in node:
                break
            node, nd, op = node[ch]
            if nd <= wl:
                best = op
            i -= 1
    if best is not None:
        nc, s, cb = best
        w = w[:nc] + s
        if cb:
            exc_trie = _EXC.get(w)
            if exc_trie is not None:
                return exc_trie
    return w


class Lemmatizer:
    """Universal Drop-In lemmatizer class with instance-owned bounded cache."""

    __slots__ = ("_cache", "_cache_size", "_cache_get")

    def __init__(self, cache_size: int = 131072) -> None:
        self._cache_size = int(cache_size)
        self._cache = dict(_EXC) if self._cache_size > 0 else {}
        if self._cache_size > 0:
            self._cache[""] = ""
        self._cache_get = self._cache.get

    def clear_cache(self) -> None:
        self._cache.clear()
        if self._cache_size > 0:
            self._cache.update(_EXC)
            self._cache[""] = ""

    def lemmatize(self, word: str) -> str:
        if self._cache_size > 0:
            cached = self._cache_get(word)
            if cached is not None:
                return cached
            w = word.lower()
            if w != word:
                cached = self._cache_get(w)
                if cached is not None:
                    if len(self._cache) >= self._cache_size:
                        self.clear_cache()
                    self._cache[word] = cached
                    return cached
            res = _lemmatize_word(word)
            if len(self._cache) >= self._cache_size:
                self.clear_cache()
            self._cache[word] = res
            return res
        return _lemmatize_word(word)

    def lemmatize_words(self, words: list[str]) -> list[str]:
        if self._cache_size > 0:
            cache = self._cache
            cache_get = self._cache_get
            cache_size = self._cache_size
            out = []
            out_append = out.append
            for word in words:
                r = cache_get(word)
                if r is not None:
                    out_append(r)
                    continue
                w = word.lower()
                if w != word:
                    r = cache_get(w)
                    if r is not None:
                        if len(cache) >= cache_size:
                            self.clear_cache()
                        cache[word] = r
                        out_append(r)
                        continue
                res = _lemmatize_word(word)
                if len(cache) >= cache_size:
                    self.clear_cache()
                cache[word] = res
                out_append(res)
            return out
        return [_lemmatize_word(w) for w in words]

    def lemmatizeWord(self, word: str) -> str:
        return self.lemmatize(word)

    def lemmatize_word(self, word: str) -> str:
        return self.lemmatize(word)

    def lemmatizeWords(self, words: list[str]) -> list[str]:
        return self.lemmatize_words(words)

    # Snowball drop-in instance aliases (D-14)
    stem = lemmatize
    stemWord = lemmatizeWord
    stem_word = lemmatize_word
    stemWords = lemmatizeWords
    stem_words = lemmatize_words

    def __call__(self, word: str) -> str:
        return self.lemmatize(word)


